CustomField.formula:
TEXT(IF(
        GC_IVR_Opt_Out_Time__c = NULL, 0,
        FLOOR(ABS(UNIXTIMESTAMP(DATETIMEVALUE(SUBSTITUTE(MID( GC_IVR_Opt_Out_Time__c, 0, 19), 'T', ' '))) - UNIXTIMESTAMP(DATETIMEVALUE(CreatedDate)))/3600)
)
)
 + 'h ' + 

TEXT(IF(
        GC_IVR_Opt_Out_Time__c = NULL, 0,
        FLOOR(MOD(ABS(UNIXTIMESTAMP(DATETIMEVALUE(SUBSTITUTE(MID( GC_IVR_Opt_Out_Time__c, 0, 19), 'T', ' '))) - UNIXTIMESTAMP(DATETIMEVALUE(CreatedDate))),3600)/60)
)
) 
 + 'm ' +

TEXT(IF(
        GC_IVR_Opt_Out_Time__c = NULL, 0,
        MOD(MOD(ABS(UNIXTIMESTAMP(DATETIMEVALUE(SUBSTITUTE(MID( GC_IVR_Opt_Out_Time__c, 0, 19), 'T', ' '))) -
        UNIXTIMESTAMP(DATETIMEVALUE(CreatedDate))),3600),60)

)
)
 + 's'
